def patch(app):
    miss = []
    for a, b in R2:
        if a in app: app = app.replace(a, b)
        elif a.replace('cửa hàng', 'điểm bán') in app: app = app.replace(a.replace('cửa hàng', 'điểm bán'), b)
        else: miss.append(a[:80])
    for a, b in [('tab <b>Đơn hàng có lỗi</b>','tab <b>Đơn lỗi</b>'),('tab <b>Cách chấm điểm</b>','tab <b>Cách chấm</b>'),
                 ('Chi tiết KPI ›','Chi tiết tiêu chí ›'),('tab <b>Chất lượng dữ liệu</b>','tab <b>Kiểm tra dữ liệu</b>')]:
        app = app.replace(a, b)
    for a, b in [('Trong phạm vi đang xem.','Trong tháng đang xem.'),("trong phạm vi NPP ","của NPP "),('dùng chung cờ đúng hạn','dùng chung kết quả đúng hạn'),
                 ('Lệch trung vị','Lệch thường gặp'),('lệch trung vị','lệch thường gặp'),('trung vị vùng','mức chung của vùng'),('Hàng chở (trung vị)','Hàng chở thường gặp'),('nên báo HEINEKEN','nên báo Ban DIP'),('mức giữa của vùng','mức trung bình của vùng'),('<b>mức giữa</b>','<b>mức trung bình</b>'),('Cách chấm điểm →','Xem cách chấm →'),('trao đổi với HEINEKEN','trao đổi với Ban DIP')]:
        app = app.replace(a, b)
    app = app.replace('Điểm bán', 'Cửa hàng').replace('điểm bán', 'cửa hàng').replace('ĐIỂM BÁN', 'CỬA HÀNG')
    return app, miss

